function overrideHtml(){const roots=configuredLibraries(),entries=roots.filter(r=>retrievalOverrides[r.id]),remaining=roots.filter(r=>!retrievalOverrides[r.id]);return '<div class="kb-overrides"><p class="kb-retrieval-help">按需添加。未独立配置的知识库继承统一参数；删除后恢复继承。</p>'+entries.map(root=>{const v=retrievalOverrides[root.id];return '<article class="kb-override-card"><div><b>'+esc(root.name)+'</b><span>独立配置</span></div><p>召回 '+esc(v.count)+' 个分片 · 最低相关度 '+esc(v.score)+'</p><p>'+esc(v.mode)+'</p><footer>'+btn('edit-override','编辑独立配置',icons.edit,'data-library="'+root.id+'"')+btn('remove-override','删除独立配置，恢复统一配置',icons.remove,'data-library="'+root.id+'"')+'</footer></article>'}).join('')+btn('add-override','添加知识库独立配置','⊕ 添加知识库独立配置','class="kb-add" '+(remaining.length?'':'disabled'))+(!roots.length?'<small>请先添加知识库检索范围。</small>':!remaining.length?'<small>已为所有选中的知识库设置独立配置。</small>':'')+'</div>'}
function openOverride(id){editingOverride=id||null;const roots=configuredLibraries().filter(r=>r.id===id||!retrievalOverrides[r.id]);if(!roots.length)return;const value=id?retrievalOverrides[id]:retrieval;modal(id?'编辑知识库独立配置':'添加知识库独立配置','<div class="kb-override-editor"><label>目录或知识库<select id="kbOverrideLibrary" '+(id?'disabled':'')+'>'+roots.map(r=>'<option value="'+r.id+'" '+(r.id===id?'selected':'')+'>'+esc(r.name)+'</option>').join('')+'</select></label><p class="kb-retrieval-help">仅对所选知识库在本智能体中的检索生效；未单独配置的知识库继续使用统一参数。</p><label>召回分片数量<input id="kbOverrideCount" type="number" min="1" max="100" step="1" value="'+esc(value.count)+'"><small>范围 1–100，仅作用于该知识库。</small></label><label>最低相关度<input id="kbOverrideScore" type="number" min="0" max="1" step="0.01" value="'+esc(value.score)+'"></label><label>索引模式<select id="kbOverrideMode">'+indexModes.map(m=>'<option '+(m===value.mode?'selected':'')+'>'+m+'</option>').join('')+'</select></label></div>','save-override')}

function active(){const q=new URLSearchParams(location.search);return q.get('module')==='reasoning'&&q.get('mode')==='configure'&&['kb','react'].includes(q.get('type')||'react')}
function defaults(){return [{id:'system',name:'系统提示词（System Prompt）',text:'# 角色定义\n你是企业知识库检索助手，负责基于已授权的知识库回答用户问题。\n\n你的目标：\n1. 理解问题并检索相关资料。\n2. 根据检索依据组织回答，标明引用来源。\n3. 问题不明确时先向用户确认。\n4. 无充分依据时说明未找到答案，不编造内容。'}]}
function btn(action,label,body,extra=''){return '<button type="button" data-kb-ui="'+action+'" aria-label="'+label+'" title="'+label+'" '+extra+'>'+body+'</button>'}
let retrievalTab='global';
function retrievalSectionHtml(){return '<section class="kb-retrieval-section"><h3>检索配置</h3><div class="kb-retrieval-tabs" role="tablist" aria-label="检索配置">'+[['global','统一配置'],['individual','独立配置']].map(([id,name])=>btn('retrieval-tab',name,name,'id="kb-retrieval-tab-'+id+'" role="tab" aria-selected="'+(retrievalTab===id)+'" aria-controls="kb-retrieval-panel-'+id+'" data-tab="'+id+'"')).join('')+'</div><div id="kb-retrieval-panel-global" role="tabpanel" aria-labelledby="kb-retrieval-tab-global" '+(retrievalTab==='global'?'':'hidden')+'>'+retrievalHtml()+'</div><div id="kb-retrieval-panel-individual" role="tabpanel" aria-labelledby="kb-retrieval-tab-individual" '+(retrievalTab==='individual'?'':'hidden')+'>'+overrideHtml()+'</div></section>'}
function retrievalHtml(){return '<label class="archive-config-switch">搜索已归档文档 <input type="checkbox" role="switch" data-archive-agent-config '+(retrieval.archived?'checked':'')+'></label>'+'<div class="kb-retrieval"><p class="kb-retrieval-help">默认应用于所有已选知识库；设置独立配置的知识库使用自己的参数。</p><label>召回分片数量<input type="number" data-kb-retrieval="count" min="1" max="100" step="1" value="'+esc(retrieval.count)+'"><small>各知识库使用的最大召回分片数量，1–100。</small></label><label>最低相关度<input type="number" data-kb-retrieval="score" min="0" max="1" step="0.01" value="'+esc(retrieval.score)+'"><small>仅保留达到该相关度的分片，范围 0–1。</small></label><label>索引模式<select data-kb-retrieval="mode">'+indexModes.map(m=>'<option '+(retrieval.mode===m?'selected':'')+'>'+m+'</option>').join('')+'</select></label><p class="kb-retrieval-help">语义：按含义匹配；全文：按关键词匹配；混合：综合两类结果；交集：保留两类检索共同命中的分片。</p><p class="kb-retrieval-error" role="alert"></p></div>'}
function retrievalError(value=retrieval){if(value.count===''||!Number.isInteger(Number(value.count))||Number(value.count)<1||Number(value.count)>100)return '召回分片数量须为 1–100 的整数。';if(value.score===''||!Number.isFinite(Number(value.score))||Number(value.score)<0||Number(value.score)>1)return '最低相关度须在 0–1 之间。';if(!indexModes.includes(value.mode))return '请选择索引模式。';return ''}
function spaceItems(base){return childrenOf(base.id)}
function selectScope(id,checked){if(!scopeNodes.has(id))return;if(checked){if(scopeChecked(id))return;resourceDraft=resourceDraft.filter(r=>!within(r.id,id));resourceDraft.push({...scopeNodes.get(id)})}else{const ancestor=resourceDraft.find(r=>within(id,r.id));resourceDraft=resourceDraft.filter(r=>!within(r.id,id)&&r!==ancestor);if(ancestor&&ancestor.id!==id){let branch=ancestor.id;while(branch!==id){const children=childrenOf(branch),next=children.find(c=>within(id,c.id));resourceDraft.push(...children.filter(c=>c!==next));if(!next)break;branch=next.id}}}}
function composerScopes(){return resources.length?[...new Map(resources.flatMap(r=>{if(r.id==='document-center')return knowledgeScopes.filter(x=>x.group==='space').flatMap(x=>spaceItems(x).filter(f=>f.kind==='folder'));const base=knowledgeScopes.find(k=>k.id===r.id&&k.group==='space');return base?spaceItems(base).filter(x=>x.kind==='folder'):(r.kind==='file'||r.id.includes('/file')?[]:[r])}).map(r=>[r.id,r])).values()]:[{id:'quality',name:'质量规范知识库',path:'当前项目 / 质量规范知识库',group:'project'},{id:'purchase',name:'采购业务知识库',path:'当前项目 / 采购业务知识库',group:'project'}]}
document.addEventListener('click',e=>{if(!active())return;const toggle=e.target.closest('[data-kb-menu-toggle]');if(toggle){e.preventDefault();e.stopImmediatePropagation();const menu=toggle.closest('.kb-turn-library'),next=!menu.open;document.querySelectorAll('.kb-turn-library').forEach(d=>{d.open=false;d.querySelector('summary').setAttribute('aria-expanded','false')});menu.open=next;toggle.setAttribute('aria-expanded',String(next));return}if(!e.target.closest('.kb-turn-library'))document.querySelectorAll('.kb-turn-library[open]').forEach(d=>{d.open=false;d.querySelector('summary').setAttribute('aria-expanded','false')})},true);
function spaceTurnState(id){return turnScopes.includes(id)?'true':turnScopes.some(x=>x.startsWith(id+'/'))?'mixed':'false'}
function updateSpaceTurn(id,folder){const folders=composerScopes().filter(r=>r.id.startsWith(id+'/')).map(r=>r.id);if(folder===undefined){const checked=spaceTurnState(id)==='true';turnScopes=turnScopes.filter(x=>x!==id&&!x.startsWith(id+'/'));if(!checked)turnScopes.push(id)}else if(!folder){turnScopes=turnScopes.filter(x=>x!==id&&!x.startsWith(id+'/'));turnScopes.push(id)}else{if(turnScopes.includes(id)){turnScopes=turnScopes.filter(x=>x!==id);turnScopes.push(...folders)}turnScopes=turnScopes.includes(folder)?turnScopes.filter(x=>x!==folder):[...turnScopes,folder]}}
function refreshSpaceTurn(id){const open=[...document.querySelectorAll('.kb-turn-library')].find(d=>d.dataset.space===id)?.open;renderFeatures();const menu=[...document.querySelectorAll('.kb-turn-library')].find(d=>d.dataset.space===id);if(menu&&open){menu.open=true;menu.querySelector('summary').setAttribute('aria-expanded','true')}}
let secondaryDirectoryEmpty=false,secondaryTagsEmpty=false;
function secondaryEnabled(kind){return features[kind]??(kind==='directory'?features.mode!=='tag':features.mode==='tag')}
function secondaryNodes(){return [...scopeNodes.values()].filter(n=>n.kind!=='file'&&resources.some(r=>within(n.id,r.id)||within(r.id,n.id)))}
function secondaryState(id){return turnScopes.some(x=>within(id,x))?'true':turnScopes.some(x=>within(x,id))?'mixed':'false'}
function toggleSecondary(id){const nodes=secondaryNodes();if(!nodes.some(n=>n.id===id))return;const ancestor=turnScopes.find(x=>within(id,x));if(ancestor){turnScopes=turnScopes.filter(x=>x!==ancestor&&!within(x,id));let branch=ancestor;while(branch!==id){const children=nodes.filter(n=>n.parent===branch),next=children.find(n=>within(id,n.id));turnScopes.push(...children.filter(n=>n!==next).map(n=>n.id));if(!next)break;branch=next.id}}else{turnScopes=turnScopes.filter(x=>!within(x,id));turnScopes.push(id)};secondaryDirectoryEmpty=turnScopes.length===0}
function refreshSecondary(menu){const openTrees=[...document.querySelectorAll('.kb-secondary-tree details[open]')].map(d=>d.dataset.treeId);renderFeatures();document.querySelectorAll('.kb-secondary-tree details').forEach(d=>d.open=openTrees.includes(d.dataset.treeId));const el=document.querySelector('[data-secondary-menu="'+menu+'"]');if(el){el.open=true;el.querySelector('summary').setAttribute('aria-expanded','true')}}
function renderArchiveTurn(){const composer=document.querySelector('.kb-composer,.react-composer');if(!composer)return;let label=composer.querySelector('[data-archive-turn-label]');if(!retrieval.archived){turnArchived=false;label?.remove();return}if(!label){label=document.createElement('label');label.dataset.archiveTurnLabel='';label.className='archive-turn-switch';label.innerHTML='检索已归档文档 <input type="checkbox" role="switch" data-archive-agent-turn>';const tools=composer.querySelector('.kb-composer-tools,.react-composer-tools');(tools||composer).append(label)}label.querySelector('input').checked=turnArchived}
document.addEventListener('change',e=>{if(e.target.matches('[data-archive-agent-config]')){retrieval.archived=e.target.checked;if(!retrieval.archived)turnArchived=false;renderArchiveTurn()}if(e.target.matches('[data-archive-agent-turn]'))turnArchived=e.target.checked});
function renderFeatures(){renderArchiveTurn();const composer=document.querySelector('.kb-composer,.react-composer');if(!composer)return;let bar=document.querySelector('.kb-turn-scopes');if(!bar){bar=document.createElement('div');bar.className='kb-turn-scopes';composer.before(bar)}const nodes=secondaryNodes();turnScopes=turnScopes.filter(id=>nodes.some(n=>n.id===id));turnTags=turnTags.filter(t=>availableTurnTags().includes(t));bar.hidden=!features.filter;if(!features.filter){bar.innerHTML='';return}const choice=(action,id,label,checked,sub='',icon='▱')=>btn(action,label,'<span class="kb-check-box">'+(checked==='true'?'✓':checked==='mixed'?'−':'')+'</span><span class="kb-secondary-icon">'+icon+'</span><span><b>'+esc(label)+'</b>'+(sub?'<small>'+esc(sub)+'</small>':'')+'</span>','class="kb-secondary-choice" role="checkbox" aria-checked="'+checked+'" data-choice="'+esc(id)+'"');const tree=(parent,depth=0)=>nodes.filter(n=>n.parent===parent).map(n=>'<div class="kb-secondary-node kb-node-'+n.kind+'" style="--depth:'+depth+'">'+choice('secondary-scope',n.id,n.name,secondaryState(n.id),n.path,n.kind==='folder'?'夹':n.kind==='space'?'空':'库')+'</div>'+tree(n.id,depth+1)).join('');const directoryLabel=secondaryDirectoryEmpty?'未选择目录或知识库':turnScopes.length?'已选 '+turnScopes.length+' 项':'全部已配置范围';const tags=availableTurnTags();bar.innerHTML=(secondaryEnabled('directory')?'<details class="kb-turn-library kb-secondary-library" data-secondary-menu="directory"><summary data-kb-menu-toggle aria-expanded="false"><span class="kb-filter-symbol">范</span><span>目录与知识库： <b>'+directoryLabel+'</b></span><span class="kb-filter-chevron">⌄</span></summary><div class="kb-turn-menu kb-secondary-panel"><header><b>选择目录与知识库</b><small>在已配置的检索范围内多选</small></header>'+choice('secondary-all','','全部已配置范围',String(!secondaryDirectoryEmpty&&!turnScopes.length),'已配置的知识库与目录','全')+'<div class="kb-secondary-tree">'+tree(null)+'</div>'+(nodes.length?'':'<p>请先配置知识库检索范围</p>')+'</div></details>':'')+(secondaryEnabled('tags')?'<details class="kb-turn-library kb-secondary-library" data-secondary-menu="tags"><summary data-kb-menu-toggle aria-expanded="false"><span class="kb-filter-symbol">#</span><span>标签： <b>'+(secondaryTagsEmpty?'未选择标签':turnTags.length?'已选 '+turnTags.length+' 项':'全部标签')+'</b></span><span class="kb-filter-chevron">⌄</span></summary><div class="kb-turn-menu kb-secondary-panel"><header><b>选择标签</b><small>与目录、知识库条件取交集，可多选</small></header>'+choice('secondary-tags-all','','全部标签',String(!secondaryTagsEmpty&&!turnTags.length),'不限标签范围','#')+'<div class="kb-secondary-tags">'+tags.map(t=>choice('secondary-tag',t,t,String(turnTags.includes(t)),'','#')).join('')+'</div>'+(tags.length?'':'<p class="kb-secondary-empty">当前检索范围内没有可用标签</p>')+'</div></details>':'')+btn('secondary-reset','重置范围','重置范围','class="kb-secondary-reset"')}

function availableTurnFiles(){return [...scopeNodes.values()].filter(r=>r.kind==='file'&&resources.some(parent=>within(r.id,parent.id))&&(!configuredTags.length||(r.tags||[]).some(t=>configuredTags.includes(t))))}
function availableTurnTags(){return configuredTags.length?[...new Set(configuredTags)]:[...new Set(availableTurnFiles().flatMap(f=>f.tags||[]))]}
function filteredTurnFiles(){const directory=features.filter&&secondaryEnabled('directory'),tags=features.filter&&secondaryEnabled('tags');if(directory&&secondaryDirectoryEmpty||tags&&secondaryTagsEmpty)return [];return availableTurnFiles().filter(f=>(!directory||!turnScopes.length||turnScopes.some(id=>within(f.id,id)))&&(!tags||!turnTags.length||(f.tags||[]).some(t=>turnTags.includes(t))))}
function turnScopeNames(){return filteredTurnFiles().map(f=>f.path)}
function normalizeResourceScopes(){resources=[...new Map(resources.filter(r=>scopeNodes.has(r.id)).map(r=>[r.id,{...scopeNodes.get(r.id)}])).values()];const ids=new Set(configuredLibraries().map(r=>r.id));Object.keys(retrievalOverrides).forEach(id=>{if(!ids.has(id))delete retrievalOverrides[id]})}
function renderResources(){normalizeResourceScopes();const host=document.querySelector('.kb-resource-config');if(!host)return;host.innerHTML='<header><div><h3>知识库检索范围</h3><p>选择平台文档中心或当前项目知识库中的内容</p></div></header>'+resources.map((r,i)=>'<div class="kb-resource-row"><span><b>'+esc(r.name)+'</b><small>'+esc(r.path)+'</small></span>'+btn('remove-scope','移除检索范围',icons.remove,'data-index="'+i+'"')+'</div>').join('')+(resources.length?'':'<p class="kb-scope-empty">暂无检索范围</p>')+btn('scopes','添加检索范围','⊕ 添加检索范围','class="kb-add"')+retrievalSectionHtml();renderFeatures()}
