function scopeContent(){const inCenter=selectedLibrary==='document-center';if(inCenter&&currentDirectory==='document-center')currentDirectory='enterprise';const node=scopeNodes.get(currentDirectory)||libraryRoots[0],q=scopeSearch.trim().toLowerCase();const rows=(q||scopeTags.length?[...scopeNodes.values()].filter(r=>r.id!==node.id&&within(r.id,node.id)):node.id==='document-center'?childrenOf(node.id).flatMap(r=>childrenOf(r.id)):childrenOf(node.id)).filter(r=>r.kind!=='space'&&(!q||(r.name+' '+r.path).toLowerCase().includes(q))&&(!scopeTags.length||(r.tags||[]).some(t=>scopeTags.includes(t))));let crumbs=[];for(let n=node;n;n=scopeNodes.get(n.parent))crumbs.unshift(n);const check=r=>'<input type="checkbox" data-kb-scope="'+r.id+'" aria-label="选择 '+esc(r.name)+'" '+(scopeChecked(r.id)?'checked':'')+' '+(scopeMixed(r.id)?'data-mixed="true"':'')+'>';return '<div class="kb-space-layout"><aside><h4>知识库</h4>'+libraryRoots.map(r=>btn('select-library',r.name,esc(r.name),'data-library="'+r.id+'" aria-pressed="'+(selectedLibrary===r.id)+'"')).join('')+'</aside><section class="kb-library-content">'+(inCenter?'<div class="kb-center-layout"><nav class="kb-space-navigation"><h4>空间组织</h4>'+knowledgeScopes.filter(r=>r.group==='space').map(r=>'<div class="kb-space-nav-row">'+check(r)+btn('open-directory',r.name,esc(r.name),'data-directory="'+r.id+'" aria-pressed="'+within(node.id,r.id)+'"')+'</div>').join('')+'</nav><div class="kb-space-documents">':'')+'<div class="kb-breadcrumb">'+crumbs.map(r=>btn('open-directory',r.name,esc(r.name),'data-directory="'+r.id+'"')).join(' / ')+'</div><input id="kbScopeSearch" placeholder="搜索当前范围的目录或文档" aria-label="搜索检索范围" value="'+esc(scopeSearch)+'"><div class="kb-file-table-scroll"><table class="kb-file-table"><thead><tr><th>'+check(node)+'</th><th>名称</th><th>类型</th><th><details class="kb-tag-filter"><summary>标签 '+(scopeTags.length?'('+scopeTags.length+')':'')+'⌄</summary><div>'+['管理制度','业务指南','有效','已审核'].map(t=>'<button type="button" class="kb-tag-choice" role="checkbox" data-scope-tag-choice="'+t+'" aria-checked="'+scopeTags.includes(t)+'"><span class="kb-check-box">'+(scopeTags.includes(t)?'✓':'')+'</span>'+t+'</button>').join('')+'<button type="button" data-clear-tags>清除筛选</button></div></details></th><th>解析状态</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+check(r)+'</td><td>'+(r.kind==='file'?esc(r.name):btn('open-directory',r.name,'▰ '+esc(r.name),'data-directory="'+r.id+'"'))+(q||scopeTags.length||node.id==='document-center'?'<small class="kb-space-path">'+esc(r.path)+'</small>':'')+'</td><td>'+esc(r.type||(r.kind==='space'?'空间组织':'知识库'))+'</td><td>'+fileTags(r)+'</td><td>'+(r.kind==='file'?'解析完成':'—')+'</td></tr>').join('')+(rows.length?'':'<tr><td colspan="5">暂无匹配资源</td></tr>')+'</tbody></table></div><small class="kb-space-path">已选择 '+resourceDraft.length+' 个范围 · 表头复选框选择当前完整范围</small>'+(inCenter?'</div></div>':'')+'</section></div>'}

