function save(){const error=retrievalError()||Object.entries(retrievalOverrides).map(([id,v])=>{const error=retrievalError(v);return error?(libraryRoots.find(r=>r.id===id)?.name||id)+'：'+error:''}).find(Boolean);if(error){if(retrievalError()){retrievalTab='global';renderResources()}status(error);const el=document.querySelector('.kb-retrieval-error');if(el)el.textContent=error;return false}try{localStorage.setItem(storageKey+':retrieval-overrides',JSON.stringify(retrievalOverrides));localStorage.setItem(storageKey+':scope-tags',JSON.stringify(configuredTags));localStorage.setItem(storageKey+':features',JSON.stringify(features));localStorage.setItem(storageKey+':retrieval',JSON.stringify({count:Number(retrieval.count),score:Number(retrieval.score),mode:retrieval.mode,archived:!!retrieval.archived}));localStorage.setItem(storageKey,JSON.stringify(prompts));localStorage.setItem(storageKey+':resources',JSON.stringify(resources));return true}catch{status('保存失败，请检查浏览器存储。');return false}}
