if(action==='send'){const input=document.querySelector('[data-agent-test-input]'),question=input.value.trim();if(!question&&!files.length)return;const answer=createCitationAnswer(question||'请参考附件回答');const stream=document.querySelector('[data-agent-chat-stream]');stream.querySelector('.agent-chat-welcome')?.remove();stream.insertAdjacentHTML('beforeend','<div class="agent-chat-message user"><b>你</b><p>'+esc(question||'请参考附件回答')+'</p><small>检索范围：'+esc(turnScopeNames().join('；')||'尚未配置')+'</small>'+files.map(f=>'<small>附件：'+esc(f.name)+'</small>').join('')+'</div>'+answer.html);renderCitations(answer.round);input.value='';files=[];renderFiles();stream.scrollTop=stream.scrollHeight;const trace=document.querySelector('[data-agent-trace-pane="chain"]');if(trace)trace.innerHTML='<div class="agent-trace-steps"><article>应用系统与自定义提示词</article><article>检索已配置知识库（演示）</article><article>整理回答与引用</article></div>'}
