document.addEventListener('input',e=>{if(active()&&e.target.dataset.kbRetrieval){retrieval[e.target.dataset.kbRetrieval]=e.target.value;const error=document.querySelector('.kb-retrieval-error');if(error)error.textContent=retrievalError();return}if(active()&&e.target.id==='kbScopeSearch'){const at=e.target.selectionStart;scopeSearch=e.target.value;renderScopePicker();const input=document.getElementById('kbScopeSearch');input.focus();input.setSelectionRange(at,at);return}if(active()&&e.target.matches('[data-agent-test-input]'))renderFiles()});
document.addEventListener('change',e=>{if(!active())return;if(e.target.dataset.turnScope){const id=e.target.dataset.turnScope;if(e.target.checked){if(!id.includes('/'))turnScopes=turnScopes.filter(x=>!x.startsWith(id+'/'));turnScopes=[...new Set([...turnScopes,id])]}else{const parent=id.split('/')[0];if(id.includes('/')&&turnScopes.includes(parent)){const base=knowledgeScopes.find(r=>r.id===parent);turnScopes=turnScopes.filter(x=>x!==parent);turnScopes.push(...base.children.map((_,i)=>parent+'/'+i).filter(x=>x!==id))}else turnScopes=turnScopes.filter(x=>x!==id)}const open=[...document.querySelectorAll('.kb-turn-library')].findIndex(d=>d.open);renderFeatures();if(open>=0){const menu=document.querySelectorAll('.kb-turn-library')[open];menu.open=true;menu.querySelector('summary').setAttribute('aria-expanded','true')}return}if(e.target.dataset.kbRetrieval){retrieval[e.target.dataset.kbRetrieval]=e.target.value;return}if(e.target.id==='kbOnlySelected'){scopeOnlySelected=e.target.checked;renderScopePicker();return}if(e.target.dataset.kbScope){selectScope(e.target.dataset.kbScope,e.target.checked);renderScopePicker();return}if(!e.target.matches('.kb-file-input'))return;const errors=[];for(const f of e.target.files){if(!/\.(pdf|docx?|txt|md)$/i.test(f.name)||f.size>50*1024*1024){errors.push(f.name);continue}if(!files.some(x=>x.name===f.name&&x.size===f.size))files.push(f)}e.target.value='';renderFiles();status(errors.length?'不支持的文件或超过 50 MB：'+errors.join('、'):'附件仅用于本次调试，不加入知识库。')});
document.addEventListener('keydown',e=>{const mask=document.querySelector('.kb-ui-mask');if(!mask)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();mask.remove()}if(e.key==='Tab'){const els=[...mask.querySelectorAll('button,input,textarea')],first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}},true);
document.addEventListener('change',e=>{if(!active())return;const id=e.target.dataset.overrideToggle;if(id){if(e.target.checked)retrievalOverrides[id]={...retrieval};else delete retrievalOverrides[id];renderResources();document.querySelector('[data-override-toggle="'+id+'"]').closest('details').open=true;return}const key=e.target.dataset.overrideKey;if(key&&retrievalOverrides[e.target.dataset.overrideId]){retrievalOverrides[e.target.dataset.overrideId][key]=e.target.value;status(retrievalError(retrievalOverrides[e.target.dataset.overrideId])||'独立配置已更新，点击顶部保存配置。')}});
